using Microsoft.AspNetCore.Identity;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Data;

public static class SeedData
{
    public static async Task InitializeAsync(IServiceProvider serviceProvider)
    {
        var roleManager = serviceProvider.GetRequiredService<RoleManager<IdentityRole>>();

        string[] roles = ["Dispatcher", "Customer"];
        foreach (var role in roles)
        {
            if (!await roleManager.RoleExistsAsync(role))
                await roleManager.CreateAsync(new IdentityRole(role));
        }

        var db = serviceProvider.GetRequiredService<ApplicationDbContext>();
        if (!db.Shipments.Any())
        {
            var now = DateTime.UtcNow;
            db.Shipments.AddRange(
                new Shipment
                {
                    TrackingNumber = "SHP-20260001",
                    Origin = "New York, USA",
                    Destination = "London, UK",
                    Status = ShipmentStatus.InTransit,
                    Description = "Electronics - 2 pallets",
                    WeightKg = 340,
                    CustomerEmail = "alice@example.com",
                    CreatedAt = now.AddDays(-3),
                    EstimatedDelivery = now.AddDays(4),
                    LastUpdated = now.AddHours(-6)
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260002",
                    Origin = "Shanghai, China",
                    Destination = "Los Angeles, USA",
                    Status = ShipmentStatus.PickedUp,
                    Description = "Textiles - 1 container",
                    WeightKg = 12500,
                    CustomerEmail = "bob@example.com",
                    CreatedAt = now.AddDays(-1),
                    EstimatedDelivery = now.AddDays(14),
                    LastUpdated = now.AddHours(-2)
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260003",
                    Origin = "Berlin, Germany",
                    Destination = "Tokyo, Japan",
                    Status = ShipmentStatus.OutForDelivery,
                    Description = "Auto parts - 5 crates",
                    WeightKg = 890,
                    CustomerEmail = "carol@example.com",
                    CreatedAt = now.AddDays(-7),
                    EstimatedDelivery = now,
                    LastUpdated = now.AddMinutes(-45)
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260004",
                    Origin = "São Paulo, Brazil",
                    Destination = "Sydney, Australia",
                    Status = ShipmentStatus.Pending,
                    Description = "Coffee beans - 3 pallets",
                    WeightKg = 2100,
                    CustomerEmail = "dave@example.com",
                    CreatedAt = now,
                    EstimatedDelivery = now.AddDays(10),
                    LastUpdated = now
                },
                new Shipment
                {
                    TrackingNumber = "SHP-20260005",
                    Origin = "Mumbai, India",
                    Destination = "Dubai, UAE",
                    Status = ShipmentStatus.Delivered,
                    Description = "Pharmaceuticals - temperature controlled",
                    WeightKg = 150,
                    CustomerEmail = "eve@example.com",
                    CreatedAt = now.AddDays(-10),
                    EstimatedDelivery = now.AddDays(-2),
                    LastUpdated = now.AddDays(-2)
                }
            );
            await db.SaveChangesAsync();
        }
    }
}

