@page "/dispatcher"

@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize(Roles = "Dispatcher")]
@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

<div class="row mb-3">
    <div class="col-md-4">
        <input type="text" class="form-control" placeholder="Filter by destination..."
               @bind="filterText" @bind:event="oninput" />
    </div>
    <div class="col-md-3">
        <select class="form-select" @bind="filterStatus">
            <option value="">All Statuses</option>
            @foreach (var status in Enum.GetValues<ShipmentStatus>())
            {
                <option value="@status">@status</option>
            }
        </select>
    </div>
    <div class="col-md-2">
        <button class="btn btn-outline-secondary w-100" @onclick="LoadShipments">
            <span class="bi bi-arrow-clockwise"></span> Refresh
        </button>
    </div>
</div>

@if (isLoading)
{
    <p><em>Loading shipments...</em></p>
}
else if (shipments is null)
{
    <div class="alert alert-danger">Failed to load shipments.</div>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><strong>@s.TrackingNumber</strong></td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "TBD")</td>
                        <td>
                            @if (editingId == s.Id)
                            {
                                <div class="d-flex gap-1">
                                    <select class="form-select form-select-sm" style="width: auto;"
                                            @bind="newStatus">
                                        @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                        {
                                            <option value="@status">@status</option>
                                        }
                                    </select>
                                    <button class="btn btn-sm btn-success" @onclick="() => SaveStatus(s.Id)"
                                            disabled="@isSaving">
                                        Save
                                    </button>
                                    <button class="btn btn-sm btn-outline-secondary" @onclick="CancelEdit">
                                        Cancel
                                    </button>
                                </div>
                            }
                            else
                            {
                                <button class="btn btn-sm btn-outline-primary"
                                        @onclick="() => StartEdit(s)">
                                    Update
                                </button>
                            }
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    <p class="text-muted">Showing @FilteredShipments.Count() of @shipments.Count shipments</p>
}

@if (statusMessage is not null)
{
    <div class="alert @(statusSuccess ? "alert-success" : "alert-danger") alert-dismissible fade show mt-2">
        @statusMessage
        <button type="button" class="btn-close" @onclick="() => statusMessage = null"></button>
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private bool isLoading = true;
    private string filterText = string.Empty;
    private string filterStatus = string.Empty;
    private int? editingId;
    private ShipmentStatus newStatus;
    private bool isSaving;
    private string? statusMessage;
    private bool statusSuccess;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
            (string.IsNullOrEmpty(filterText) ||
             s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)) &&
            (string.IsNullOrEmpty(filterStatus) ||
             s.Status.ToString() == filterStatus));

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        isLoading = true;
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        finally
        {
            isLoading = false;
        }
    }

    private void StartEdit(ShipmentDto shipment)
    {
        editingId = shipment.Id;
        newStatus = shipment.Status;
    }

    private void CancelEdit()
    {
        editingId = null;
    }

    private async Task SaveStatus(int id)
    {
        isSaving = true;
        statusMessage = null;
        try
        {
            var success = await ShipmentService.UpdateShipmentStatusAsync(id, newStatus);
            if (success)
            {
                statusMessage = "Status updated successfully.";
                statusSuccess = true;
                editingId = null;
                await LoadShipments();
            }
            else
            {
                statusMessage = "Failed to update status.";
                statusSuccess = false;
            }
        }
        finally
        {
            isSaving = false;
        }
    }

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

